#include <TFT_eSPI.h>
TFT_eSPI tft;

void setup() {
  tft.init();
  tft.setRotation(0);

  struct Item { const char* name; uint16_t color; };
  Item items[12] = {
    { "RED",    TFT_RED },
    { "ORANGE", TFT_ORANGE },
    { "YELLOW", TFT_YELLOW },
    { "GREEN",  TFT_GREEN },
    { "CYAN",   TFT_CYAN },
    { "BLUE",   TFT_BLUE },
    { "MAGENTA",TFT_MAGENTA },
    { "WHITE",  TFT_WHITE },
    { "BLACK",  TFT_BLACK },
    { "PINK",   TFT_PINK },
    { "LIME",   TFT_LIME },
    { "PURPLE", TFT_PURPLE }
  };

  int C = 4;
  int R = 3;
  int w = tft.width() / C;
  int h = tft.height() / R;

  for (int i = 0; i < 12; i++) {
    int x = (i % C) * w;
    int y = (i / C) * h;
    tft.fillScreenRegion(x, y, x + w - 1, y + h - 1, items[i].color);
    tft.setTextColor(TFT_BLACK);
    tft.setTextSize(1);
    tft.drawString(items[i].name, x + 3, y + h / 2);
  }
}

void loop() {}
